    public static void testAFinishedUnitIsFoldedIntoTheTotals() {
        emon.Planctx.Plan p = new emon.Planctx.Plan();
        tInit(p, 5, 24);
        Planloop.plAttempt(p);
        Planloop.plAfter(p, Plan.usNeedBytes());
        Planloop.plAttempt(p);
        tRender(p, 1);
        tRender(p, 2);
        Planloop.plAfter(p, Plan.usRequests());
        p.bytesRequests = 4;
        Planloop.plFold(p);
        emon.Testport.assertEq(p.tAttempts, 2, "attempts");
        emon.Testport.assertEq(p.tFetchRounds, 1, "fetch rounds");
        emon.Testport.assertEq(p.tBytesRequests, 4, "bytes requests");
        emon.Testport.assertEq(p.tRequests, 2, "requests");
        emon.Testport.assertEq(p.attempts, 0, "the unit is reset");
        emon.Testport.assertEq(emon.Port.cellsLen(p.ans), 0, "its answers are gone");
        Planloop.enNext(p, 1, 1, 0, 2);
        Planloop.plAttempt(p);
        tRender(p, 3);
        Planloop.plAfter(p, Plan.usRequests());
        Planloop.plFold(p);
        emon.Testport.assertEq(p.tAttempts, 3, "the asset unit counts its attempts too");
        emon.Testport.assertEq(p.tRequests, 3, "and its requests");
        Planloop.enNext(p, 1, 1, 0, 2);
        Planloop.plAttempt(p);
        tRender(p, 4);
        tRender(p, 5);
        Planloop.plAfter(p, Plan.usRequests());
        Planloop.plFold(p);
        emon.Testport.assertEq(p.tAttempts, 3, "a page unit does not count its attempts");
        emon.Testport.assertEq(p.tRequests, 5, "but its requests");
        emon.Testport.assertEq(emon.Port.cellsLen(p.pgq), 1, "it keeps the requests it made");
        emon.Testport.assertEq(emon.Port.cellsAt(p.pgq, 0), 2, "two");
        emon.Testport.assertEq(emon.Port.cellsAt(p.pgr, 0), 1, "in one round");
    }
