    public static void testTheSpansOfAnInputARequestNames() {
        emon.Port.Cells c = emon.Port.newCells();
        emon.Port.Cells o = emon.Port.newCells();
        Plan.rqDecode(c, 1, 0, 100, 50, 0, 0);
        Plan.rqDecode(c, 2, 3, 100, 50, 0, 0);
        Plan.rqDecode(c, 3, 0, -1, 50, 0, 0);
        Plan.rqDecode(c, 4, 0, 100, 0, 0, 0);
        Plan.rqRender(c, 5, 0, 0, 144, 0);
        emon.Testport.assertEq(Planloop.plSpans(c, 0, 0, o), 1, "a decode of this input");
        emon.Testport.assertEq(emon.Port.cellsAt(o, 0), 100, "its offset");
        emon.Testport.assertEq(emon.Port.cellsAt(o, 1), 50, "its length");
        emon.Testport.assertEq(Planloop.plSpans(c, 8, 0, o), 0, "a decode of another input");
        emon.Testport.assertEq(Planloop.plSpans(c, 16, 0, o), 0, "a decode at a negative offset");
        emon.Testport.assertEq(Planloop.plSpans(c, 24, 0, o), 0, "a decode of no bytes");
        emon.Testport.assertEq(Planloop.plSpans(c, 32, 0, o), 0, "a render names no bytes");
        emon.Testport.assertEq(emon.Port.cellsLen(o), 2, "nothing else was written");
    }
    public static int tZeros(emon.Port.Cells c, int n) {
        // Append n zeros: the words of two SHA-256s, or a residency map with nothing resident.
        int i = 0;
        while (i < n) {
            emon.Port.cellsPush(c, 0);
            i += 1;
        }
        return 0;
    }
